/**
 * Shared Document AI contracts. Normative prose lives in docs/contracts.md.
 * Safe to import from both server and client: no node-only imports.
 * Owner: architect. Other roles propose changes; they do not edit this file.
 */
import type { UserRole } from './domain';

// ---------------------------------------------------------------- Constants

export const DOCUMENT_AI_API_BASE = '/api/document-ai';

export const DOCUMENT_AI_LIMITS = {
  /** One document (a direct upload or one file inside a ZIP). */
  maxFileBytes: 100 * 1024 * 1024,
  /** One upload request: a ZIP of many documents, streamed to disk. DOCUMENT_AI_MAX_UPLOAD_MB overrides it. */
  maxUploadBytes: 2 * 1024 * 1024 * 1024,
  maxFilesPerSession: 300,
  maxSessionBytes: 1 * 1024 * 1024 * 1024,
  /** Uncompressed XLSX ceiling, zip-bomb guard. */
  maxXlsxUncompressedBytes: 60 * 1024 * 1024,
  maxOriginalNameLength: 120,
  maxSnippetLength: 300,
  previewMaxRows: 200,
  previewMaxColumns: 40,
} as const;

export const DOCUMENT_AI_THRESHOLDS = {
  defaultAutoApply: 0.85,
  minAutoApply: 0.7,
  maxAutoApply: 0.99,
  /** Below this a candidate is dropped and only counted. */
  discardBelow: 0.5,
  /** Review-panel badges: at or above is High, at or above mediumFrom is Medium, below is Low. */
  highConfidenceFrom: 0.9,
  mediumConfidenceFrom: 0.75,
  /** Relative tolerance for currency comparison, plus an absolute 1 rupee. */
  currencyRelativeTolerance: 0.005,
  currencyAbsoluteTolerance: 1,
} as const;

export const DOCUMENT_AI_DEFAULT_SETTINGS = {
  enabled: true,
  autoApplyThreshold: DOCUMENT_AI_THRESHOLDS.defaultAutoApply,
  retentionDays: 30,
} as const;

export const DOCUMENT_AI_RETENTION_RANGE = { min: 1, max: 365 } as const;
export const UNLINKED_SESSION_TTL_HOURS = 72;

export const DOCUMENT_SESSION_ID_PATTERN = /^ds_[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
export const DOCUMENT_ID_PATTERN = /^doc_[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
export const JOB_ID_PATTERN = /^job_[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;

// -------------------------------------------------------------- Enumerations

export const FIELD_STATUSES = [
  'auto_applied',
  'needs_verification',
  'conflict',
  'rejected_validation',
] as const;
export type FieldStatus = (typeof FIELD_STATUSES)[number];

export const DOCUMENT_TYPES = [
  'gst_return',
  'gst_certificate',
  'bank_statement',
  'financial_statement', // balance sheet and/or P&L, audited or not
  'itr',
  'pan_card',
  'credit_report',
  'registration_certificate', // incorporation, Udyam, partnership/LLP deed
  'loan_application', // the borrower's request: application, sanction request
  'existing_sanction_letter', // a lender's letter about an EXISTING facility
  'cma_projection',
  'collateral_valuation',
  'quotation_invoice',
  'other',
] as const;
export type DocumentType = (typeof DOCUMENT_TYPES)[number];

export const ACCEPTED_FILE_KINDS = ['pdf', 'xlsx', 'csv', 'png', 'jpeg', 'webp', 'docx', 'txt'] as const;
/** A ZIP is not stored: each file inside is validated and stored as its own document. */
export const ZIP_UPLOAD_LIMITS = { maxEntries: 25, maxTotalUncompressedBytes: 60 * 1024 * 1024 } as const;
export type AcceptedFileKind = (typeof ACCEPTED_FILE_KINDS)[number];

export const FILE_KIND_MIME: Record<AcceptedFileKind, string> = {
  pdf: 'application/pdf',
  xlsx: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  csv: 'text/csv',
  png: 'image/png',
  jpeg: 'image/jpeg',
  webp: 'image/webp',
  docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  txt: 'text/plain',
};

export const FILE_KIND_EXTENSION: Record<AcceptedFileKind, string> = {
  pdf: 'pdf',
  xlsx: 'xlsx',
  csv: 'csv',
  png: 'png',
  jpeg: 'jpg',
  webp: 'webp',
  docx: 'docx',
  txt: 'txt',
};

export type FieldValue = string | number;

/** Why a field landed in its status. Machine-readable; the UI maps these to copy. */
export type FieldReasonCode =
  | 'low_confidence'
  | 'validation_failed'
  | 'value_not_in_snippet'
  | 'unexpected_source_type'
  | 'derived_value'
  | 'injection_suspected'
  | 'identity_mismatch'
  | 'multiple_subjects'
  | 'values_differ'
  | 'non_inr_currency'
  | 'ambiguous_unit'
  | 'period_unknown'
  | 'superseded_period'
  | 'fallback_source'
  /** Not found in the text the server read itself, or that text could not be read. */
  | 'not_in_source'
  /** An enum that a person always confirms: explicit requests and GST compliance. */
  | 'enum_review_required'
  /** The snippet has none of the evidence keywords defined for the option. */
  | 'enum_no_evidence'
  /** A positive figure on a signed field whose wording says loss, deficit or similar. */
  | 'loss_wording'
  /** The unit in rawValue, the stated unit, the unit text and the snippet do not agree. */
  | 'unit_mismatch'
  /** The snippet or unit text carries a non-INR unit. */
  | 'non_inr_unit'
  /** An annual flow field read from a part-year date, range or wording. */
  | 'part_year_period';

export type ExtractionErrorCode =
  | 'password_protected'
  | 'unreadable_document'
  | 'llm_not_configured'
  | 'llm_rate_limited'
  | 'llm_quota_exhausted'
  | 'llm_timeout'
  | 'llm_invalid_response'
  | 'llm_failed'
  | 'interrupted'
  /** Turned away by the memory gate: the server was too busy to read the file safely. Retryable. */
  | 'server_busy'
  | 'file_missing';

export type DocumentAiErrorCode =
  | ExtractionErrorCode
  | 'unauthenticated'
  | 'forbidden'
  | 'auth_not_configured'
  | 'too_many_attempts'
  | 'disabled'
  | 'invalid_request'
  | 'invalid_session_id'
  | 'not_found'
  | 'file_too_large'
  | 'too_many_files'
  | 'session_too_large'
  | 'unsupported_type'
  | 'type_mismatch'
  | 'job_in_progress'
  | 'internal_error';

export interface DocumentAiErrorBody {
  /** Same key as existing routes, so requestJson-style handling works. Never contains borrower data. */
  error: string;
  code: DocumentAiErrorCode;
  jobId?: string;
}

// ------------------------------------------------------- Extraction payloads

export interface SourceRef {
  documentId: string;
  fileName: string;
  documentType: DocumentType;
  /** 1-based PDF page. Null for spreadsheets, CSV and images. */
  page: number | null;
  sheetName: string | null;
  /** Spreadsheet cell, or 'row:<n>' for CSV. */
  cellRef: string | null;
  /** Verbatim text from the document, at most maxSnippetLength characters. Untrusted: render as text. */
  snippet: string;
}

export type AmountUnit = 'rupees' | 'thousand' | 'lakh' | 'crore' | 'million';

/**
 * Outcome of checking a candidate against text the server read itself. Merge is pure and holds no
 * document text, so this is set once at extraction and stored with the candidate.
 * no_text: nothing to check against (image, scanned PDF). Absent reads the same.
 */
export type SourceCheck = 'verified' | 'failed' | 'no_text';

/**
 * A negative the server itself read. `negative_figure`: the spreadsheet cell holding the value is
 * negative. `negative_in_row`: another figure in its row or printed line is.
 */
export type SourceSign = 'negative_figure' | 'negative_in_row';

/** One value, from one place in one document. */
export interface ExtractedField {
  /** Stable within a document result: `${documentId}:${fieldId}:${n}`. */
  candidateId: string;
  fieldId: string;
  /** Normalised. A real 0 is 0. Absent values never appear as candidates. */
  value: FieldValue | null;
  /** Text as read from the document, before normalisation. */
  rawValue: string;
  confidence: number;
  source: SourceRef;
  status: FieldStatus;
  reasons: FieldReasonCode[];
  /** 'FY 2024-25', or a date for point-in-time data. Null when the document does not state it. */
  period: string | null;
  /** Masked subject: account last 4, or person name for a credit report. Never a full account number. */
  subjectRef: string | null;
  /** The model's reading of the table or page header. Null when it stated none. */
  statedUnit?: AmountUnit | null;
  /** Verbatim header text behind statedUnit, such as "(Rs. in lakhs)". Untrusted: render as text. */
  unitText?: string | null;
  sourceCheck?: SourceCheck;
  /** Row text the server read beside the value, for signed and currency fields. Untrusted: render as text. */
  rowLabel?: string | null;
  /** A negative the server read at the value, on signed and currency fields. Absent when it read none. */
  sourceSign?: SourceSign | null;
  /** Scale headers the server read on the cited page or sheet, for currency fields. Absent when it read none. */
  scaleHeaders?: AmountUnit[];
  /** Computed from printed figures by a deterministic reader and proved by arithmetic (sums to a printed total). */
  reconciled?: boolean;
  /** Present on server-computed values: the rule and the candidates it used. */
  derivation?: { ruleId: DerivationRuleId; fromCandidateIds: string[] };
}

export type DerivationRuleId =
  | 'vintage_from_establishment_date'
  | 'profitability_from_pat'
  | 'average_monthly_from_bank_table'
  | 'gst_compliance_mirror'
  /** gstAnnualTurnover: the sum over GSTR-3B returns covering all 12 months of one FY. */
  | 'annual_from_gst_monthly_returns'
  /** Review-only summary of the GSTR-3B months read, with missing months named. */
  | 'gst_monthly_returns_summary';

/** Merged, per-field view across a session. This is what the form consumes. */
export interface FieldResult {
  fieldId: string;
  status: FieldStatus;
  /** Null for conflict and rejected_validation. Set for the other two. */
  value: FieldValue | null;
  confidence: number;
  source: SourceRef | null;
  reasons: FieldReasonCode[];
  /** Every candidate, including those from older periods. */
  candidates: ExtractedField[];
  /** Precedence suggestion on a conflict. Display only, never auto-applied. */
  suggestedCandidateId: string | null;
  /** Set when this result was copied from a primary field. */
  mirrorOf: string | null;
  /** Field is in editedFields, so the form value stands and this is shown for review only. */
  overriddenByUser: boolean;
}

/** Monthly row supplied by the model for bank statements; the server does the arithmetic. */
export interface BankMonthlyTotal {
  month: string; // YYYY-MM
  totalCredits: number | null;
  closingBalance: number | null;
  /** From the model, 0 to 1. A derived value takes the lowest among its inputs. */
  confidence: number;
  subjectRef: string | null;
  source: SourceRef;
  /** `failed` when the server could not read the file: an average of this row carries not_in_source. */
  sourceCheck?: SourceCheck;
  /** First and last day (YYYY-MM-DD) the statement this row came from covers. */
  coverFrom?: string;
  coverTo?: string;
  /** The statement is cut off (a capped online statement): never used for an average. */
  partial?: boolean;
}

/**
 * One GSTR-3B return's Table 3.1 as printed, parsed by the server. Each figure is the "Total taxable
 * value" column of its row. The server adds (a)+(b)+(c) only when deriving; (d) inward supplies on
 * reverse charge are never read, and (e) non-GST supplies are kept for display and never counted.
 */
export interface GstReturnPeriodTotal {
  form: 'GSTR-3B';
  /** 'FY 2025-26', from the return's printed Year. */
  financialYear: string;
  /** YYYY-MM months the return covers: one for a monthly return, three for a quarterly one. */
  months: string[];
  /** 3.1(a) Outward taxable supplies (other than zero rated, nil rated and exempted). */
  outwardTaxable: number;
  /** 3.1(b) Outward taxable supplies (zero rated). */
  zeroRated: number;
  /** 3.1(c) Other outward supplies (nil rated, exempted). */
  nilExempt: number;
  /** 3.1(e) Non-GST outward supplies, or null when the row was not read. Never counted. */
  nonGst: number | null;
  /** The supplier's GSTIN printed on the return, validated, or null. Returns of different GSTINs are never added up. */
  gstin: string | null;
  confidence: number;
  source: SourceRef;
}

export interface DocumentExtractionSuccess {
  ok: true;
  documentId: string;
  documentType: DocumentType;
  classificationConfidence: number;
  fields: ExtractedField[];
  bankMonthlyTotals: BankMonthlyTotal[];
  /** GSTR-3B Table 3.1 periods read by the server. Absent on results stored before this existed. */
  gstReturnPeriods?: GstReturnPeriodTotal[];
  injectionSuspected: boolean;
  /** Candidates dropped below discardBelow. Counted, never stored. */
  droppedLowConfidence: number;
  /** Model name, for audit. */
  model: string;
}

export interface DocumentExtractionFailure {
  ok: false;
  documentId: string;
  errorCode: ExtractionErrorCode;
}

export type DocumentExtractionResult = DocumentExtractionSuccess | DocumentExtractionFailure;

// -------------------------------------------------- Pipeline <-> routes seam

/** Argument of extractDocument, exported by server/documentAi/pipeline.ts. */
export interface ExtractDocumentInput {
  documentId: string;
  /** Sanitised original name. Goes on SourceRef only; never into the prompt. */
  fileName: string;
  kind: AcceptedFileKind;
  bytes: Uint8Array;
  /** Set when the user overrode classification. */
  declaredDocumentType: DocumentType | null;
  /** Today's date, YYYY-MM-DD, so results are reproducible in tests. */
  today: string;
  /** Aborted at the per-file timeout. */
  signal: AbortSignal;
  /** The job reading the file, for the per-job model circuit breaker. Never logged or stored by the pipeline. */
  jobId?: string;
}

/** Argument of mergeSessionResults. Must stay pure: no I/O, no clock. */
export interface MergeSessionInput {
  documents: DocumentExtractionSuccess[];
  editedFieldIds: string[];
  autoApplyThreshold: number;
  today: string;
}

export interface MergeSessionOutput {
  fields: Record<string, FieldResult>;
  warnings: SessionWarning[];
}

export interface SessionWarning {
  code: 'identity_mismatch' | 'injection_suspected' | 'multiple_subjects';
  documentIds: string[];
  fieldIds: string[];
}

export interface SpreadsheetPreview {
  sheets: Array<{ name: string; rows: string[][]; truncated: boolean }>;
}

// ----------------------------------------------------------- Stored records

export type DocumentProcessingStatus =
  | 'uploaded'
  | 'queued'
  | 'extracting'
  | 'extracted'
  | 'failed';

export interface StoredDocument {
  documentId: string;
  sessionId: string;
  /** Sanitised, for display only. Never used to build a path. */
  originalName: string;
  /** Derived from magic bytes, never from the client. */
  kind: AcceptedFileKind;
  mimeType: string;
  sizeBytes: number;
  sha256: string;
  uploadedAt: string;
  uploadedBy: string;
  status: DocumentProcessingStatus;
  errorCode: ExtractionErrorCode | null;
  documentType: DocumentType | null;
  /** True when the user set documentType; extraction then honours it. */
  documentTypeOverridden: boolean;
  /** Set once bytes are gone; provenance may remain. */
  fileDeletedAt: string | null;
  fileDeletedReason: 'user' | 'retention' | null;
}

export type EditOrigin =
  | 'typed'
  | 'cleared'
  | 'accepted_document_value'
  | 'resolved_conflict'
  | 'demo_sample'
  | 'preexisting_value';

export interface EditedFieldEntry {
  fieldId: string;
  origin: EditOrigin;
  at: string;
  /** For accepted_document_value and resolved_conflict. */
  candidateId?: string;
}

export interface AppliedFieldEntry {
  fieldId: string;
  candidateId: string;
  at: string;
}

/** Persisted as edits.json. Holds field IDs only, never values. */
export interface SessionEdits {
  editedFields: Record<string, EditedFieldEntry>;
  appliedFields: Record<string, AppliedFieldEntry>;
  revision: number;
  updatedAt: string;
}

export interface DocumentSessionRecord {
  sessionId: string;
  assessmentId: string | null;
  createdAt: string;
  updatedAt: string;
  linkedAt: string | null;
  /** Set when the assessment was deleted without a document session. Files then wait for normal retention. */
  detachedAt?: string | null;
  createdBy: string;
}

export type ExtractionJobStatus =
  | 'queued'
  | 'running'
  | 'completed'
  | 'completed_with_errors'
  | 'failed';

export const TERMINAL_JOB_STATUSES: readonly ExtractionJobStatus[] = [
  'completed',
  'completed_with_errors',
  'failed',
];

export interface ExtractionJob {
  jobId: string;
  sessionId: string;
  status: ExtractionJobStatus;
  documentIds: string[];
  /** Documents finished so far, successful or not. */
  processed: number;
  errors: Array<{ documentId: string; code: ExtractionErrorCode }>;
  createdAt: string;
  startedAt: string | null;
  finishedAt: string | null;
}

export interface DocumentAiSettings {
  enabled: boolean;
  /** Inclusive, in [minAutoApply, maxAutoApply]. */
  autoApplyThreshold: number;
  retentionDays: number;
  updatedAt: string | null;
  updatedBy: string | null;
}

// ------------------------------------------------------------ Activity log

export const ACTIVITY_EVENT_TYPES = [
  'auth_session_created',
  'auth_session_failed',
  'auth_logout',
  'session_created',
  'session_linked',
  'session_detached',
  'file_uploaded',
  'file_rejected',
  'file_previewed',
  'file_downloaded',
  'file_deleted',
  'fields_cleared',
  'document_type_overridden',
  'extraction_queued',
  'extraction_started',
  'extraction_document_completed',
  'extraction_document_failed',
  'extraction_completed',
  'injection_suspected',
  'field_edited',
  'field_accepted',
  'conflict_resolved',
  'settings_changed',
  'retention_purged',
  'unlinked_session_purged',
] as const;
export type ActivityEventType = (typeof ACTIVITY_EVENT_TYPES)[number];

/** Allowlist by shape: there is deliberately no free-text or value field. */
export interface ActivityEvent {
  id: string;
  at: string;
  type: ActivityEventType;
  actor: string;
  sessionId: string | null;
  assessmentId: string | null;
  documentId: string | null;
  jobId: string | null;
  /** Sanitised, with PAN/GSTIN-shaped substrings masked. */
  fileName: string | null;
  fieldIds: string[];
  /** Enumerated code, such as an error code, delete mode, or file kind. */
  code: string | null;
  /** Counts only, such as field or byte counts. */
  counts: Record<string, number>;
}

// ------------------------------------------------------------ API payloads

export interface DocumentActor {
  id: string;
  /** Self-reported at unlock. Attribution, not proof of identity. */
  email: string;
  displayName: string;
  role: UserRole;
  via: 'access_code' | 'local_dev';
}

export interface AuthStatusResponse {
  authenticated: boolean;
  /** False in production when no access code is configured: the feature is closed. */
  configured: boolean;
  actor: DocumentActor | null;
}

export interface CreateAuthSessionRequest {
  accessCode: string;
  actorEmail?: string;
  actorDisplayName?: string;
}

export interface UploadDocumentRequest {
  fileName: string;
  /** Advisory only. Kind comes from magic bytes. */
  mimeType?: string;
  base64: string;
}

export interface UploadDocumentResponse {
  document: StoredDocument;
  /** A ZIP upload: every document stored from it, and the files inside it that could not be used. */
  documents?: StoredDocument[];
  skipped?: Array<{ fileName: string; reason: string }>;
  /** True when the same bytes are already in this session; `document` is the existing one. */
  duplicate: boolean;
}

export interface ListDocumentsResponse {
  documents: StoredDocument[];
}

export interface StartExtractionRequest {
  /** Omit for every document not yet extracted or previously failed. */
  documentIds?: string[];
  /** Re-run documents already extracted. */
  force?: boolean;
}

export interface StartExtractionResponse {
  job: ExtractionJob;
}

export interface JobStatusResponse {
  job: ExtractionJob;
}

/** Full client hydrate. Also returned by the mutations that change merged results. */
export interface DocumentSessionState {
  session: DocumentSessionRecord;
  documents: StoredDocument[];
  fields: Record<string, FieldResult>;
  warnings: SessionWarning[];
  edits: SessionEdits;
  activeJob: ExtractionJob | null;
}

export interface UpdateEditsRequest {
  setEdited?: EditedFieldEntry[];
  clearEdited?: string[];
  setApplied?: AppliedFieldEntry[];
  clearApplied?: string[];
}

export interface UpdateDocumentRequest {
  documentType: DocumentType;
}

export type DeleteDocumentMode = 'file_only' | 'file_and_clear_fields';

export interface DeleteDocumentResponse {
  /** Client must blank these unless edited; the server cannot touch form state. */
  clearFieldIds: string[];
  state: DocumentSessionState;
}

export interface LinkSessionRequest {
  assessmentId: string;
}

export interface FindSessionResponse {
  session: DocumentSessionRecord | null;
}

export interface DocumentAiSettingsResponse {
  settings: DocumentAiSettings;
  /** DOCUMENT_AI_ENABLED=false on the server overrides settings.enabled. */
  disabledByEnv: boolean;
  /** GEMINI_API_KEY presence, as a boolean only. */
  llmConfigured: boolean;
}

export type UpdateDocumentAiSettingsRequest = Partial<
  Pick<DocumentAiSettings, 'enabled' | 'autoApplyThreshold' | 'retentionDays'>
>;
